// MARK: - Thread-Safe ModelContext Access
// Ensures all SwiftData operations are synchronized
@MainActor
final class ModelContextActor {
    private let modelContext: ModelContext

    init(modelContext: ModelContext) {
        self.modelContext = modelContext
    }

    func performOperation<T>(_ operation: (ModelContext) throws -> T) throws -> T {
        return try operation(modelContext)
    }
}

