    func spendPoints(_ amount: Int, reason: String) -> Bool {
        // VALIDATION: Prevent manipulation
        guard validateSpending(amount: amount, reason: reason) else {
            print("⚠️ FP spending validation failed: \(amount) for \(reason)")
            return false
        }

        // Check sufficient balance
        guard currentPoints >= amount else {
            print("⚠️ Insufficient FP balance: \(currentPoints) < \(amount)")
            return false
        }

        let transaction = PointTransaction(
            id: UUID(),
            amount: amount,
            reason: reason,
            type: .spent,
            timestamp: Date()
        )

        withAnimation(.spring(response: 0.5, dampingFraction: 0.7)) {
            currentPoints = max(0, currentPoints - amount) // Don't go negative
            todaySpent += amount
            lastChange = -amount
            isAnimating = true
        }

        pointHistory.insert(transaction, at: 0)
        savePoints()

        // Reset animation
        DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
            self.isAnimating = false
        }

        return true
    }

    private func validateSpending(amount: Int, reason: String) -> Bool {
        // Amount validation
        guard amount > 0 && amount <= 10000 else {
            return false // Prevent negative or excessive amounts
        }

        // Rate limiting - max 50 spending transactions per hour
        let hourAgo = Date().addingTimeInterval(-3600)
        let recentSpending = pointHistory.filter { 
            $0.timestamp > hourAgo && $0.type == .spent
        }
        guard recentSpending.count < 50 else {
            return false // Too many spending transactions
        }

        // Reason validation - ensure it's a legitimate spending reason
        let validReasons = [
            "Theme purchase", "Power-up", "Skip penalty", "Break extension",
            "Unlock feature", "Custom reward", "Store purchase"
        ]

        let isValidReason = validReasons.contains { reason.contains($0) } ||
                          reason.hasPrefix("Unlock") ||
                          reason.hasPrefix("Purchase")

        return isValidReason
    }

