        let weekTotal = analyticsManager.weeklyData.reduce(0) { $0 + $1.screenTime }
        let weekAvg = weekTotal / 7
        let todayScreenHours = analyticsManager.todayScreenTime / 3600

        // Find best day
        let bestDay = analyticsManager.weeklyData.max(by: { $0.focusTime < $1.focusTime })
        let bestDayName = bestDay?.day ?? "today"
        let bestFocusMinutes = Int((bestDay?.focusTime ?? 0) * 60)

        // Generate insight based on data
        if analyticsManager.currentStreak > 2 {
            return "You're on a \(analyticsManager.currentStreak)-day focus streak! Your best day was \(bestDayName) with \(bestFocusMinutes) minutes of deep focus."
        } else if todayScreenHours < weekAvg {
            let decrease = Int(((weekAvg - todayScreenHours) / weekAvg) * 100)
            return "Your screen time is \(decrease)% lower than your weekly average! Keep up the great work."
        } else if analyticsManager.focusScore > 60 {
            return "Your focus score is \(analyticsManager.focusScore)! You're maintaining excellent focus habits."
