    /// Simplified setup using SessionCoordinator
    func setupWithCoordinator(
        constellationViewModel: ConstellationViewModel? = nil,
        dopamineDebtViewModel: DopamineDebtViewModel? = nil,
        hapticEngine: HapticEngine? = nil
    ) {
        let coordinator = SessionCoordinator.shared
        let observerKey = "SessionCoordinator.focusObservers"

        unregisterFocusObservers(for: observerKey)

        // Start handler
        registerFocusStartObserver(observerKey) { duration in
            coordinator.startSession(duration: duration)
            constellationViewModel?.startNewSession(focusDuration: duration)
        }

        // Progress handler
        registerFocusProgressObserver(observerKey) { elapsed in
            coordinator.updateProgress(
                elapsedMinutes: elapsed,
                totalMinutes: max(self.totalTime / 60, 1)
            )
            constellationViewModel?.updateSessionProgress(elapsedMinutes: elapsed)
        }

        // Abandon handler
        registerFocusAbandonObserver(observerKey) {
            coordinator.abandonSession(
                elapsedMinutes: (self.totalTime - self.timeRemaining) / 60,
                plannedMinutes: self.totalTime / 60,
                constellationViewModel: constellationViewModel
            )
            hapticEngine?.playEmergencyPause()
        }

        // Complete handler
        registerFocusCompleteObserver(observerKey) { minutes in
            let result = coordinator.completeSession(
                actualMinutes: minutes,
                plannedMinutes: self.totalTime / 60,
                timerViewModel: self,
                constellationViewModel: constellationViewModel,
                dopamineDebtViewModel: dopamineDebtViewModel
            )

            // Handle achievements if needed
            if !result.achievements.isEmpty {
                // Could trigger achievement notifications here
                print("Achievements unlocked: \(result.achievements)")
            }
        }
    }
}
