                let now = Date()
                let calendar = Calendar.current
                let currentDay = calendar.component(.weekday, from: now)

                guard daysOfWeek.contains(currentDay) else { return false }

                let currentTimeComponents = calendar.dateComponents([.hour, .minute], from: now)
                let startComponents = calendar.dateComponents([.hour, .minute], from: startTime)
                let endComponents = calendar.dateComponents([.hour, .minute], from: endTime)

                guard let currentHour = currentTimeComponents.hour,
                      let currentMinute = currentTimeComponents.minute,
                      let startHour = startComponents.hour,
                      let startMinute = startComponents.minute,
                      let endHour = endComponents.hour,
                      let endMinute = endComponents.minute else {
