        var levelReachDays: [Int: [Int]] = [:] // level -> days to reach
        var questCompletionRates: [String: Double] = [:] // category -> rate

        var percentReachedLevel2Day1: Double {
            guard totalUsers > 0 else { return 0 }
            return Double(usersReachedLevel2Day1) / Double(totalUsers) * 100
        }

        var medianFPPerDay: Double {
            guard !dailyFPEarned.isEmpty else { return 0 }
            let sorted = dailyFPEarned.sorted()
            let count = sorted.count
            if count % 2 == 0 {
                return Double(sorted[count/2 - 1] + sorted[count/2]) / 2
            } else {
                return Double(sorted[count/2])
            }
        }

        var percentHittingDailyCap: Double {
            guard !dailyFPEarned.isEmpty else { return 0 }
            return Double(dailyCapHits) / Double(dailyFPEarned.count) * 100
        }

        func medianDaysToLevel(_ level: Int) -> Double? {
            guard let days = levelReachDays[level], !days.isEmpty else { return nil }
            let sorted = days.sorted()
            let count = sorted.count
            if count % 2 == 0 {
                return Double(sorted[count/2 - 1] + sorted[count/2]) / 2
            } else {
                return Double(sorted[count/2])
            }
        }
    }

